<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
    <style>
        body {
            margin: 0;
            padding: 40px 50px;
            font-family: Georgia, serif;
            line-height: 1.5;
            color: #000;
        }
        .title {
            font-size: 18pt;
            font-weight: bold;
            text-align: center;
            margin-bottom: 30px;
            border-bottom: 2px solid #000;
            padding-bottom: 10px;
        }
        .header {
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
            margin-bottom: 40px;
            border-bottom: 1px solid #000;
            padding-bottom: 15px;
        }
        .left, .right {
            font-size: 12pt;
        }
        .right {
            text-align: right;
        }
        .address {
            margin-bottom: 30px;
            line-height: 1.4;
        }
        .content {
            margin-bottom: 30px;
            line-height: 1.6;
        }
        .content p {
            margin-bottom: 12px;
        }
        .centered {
            text-align: center;
            margin: 30px 0;
        }
        .signature {
            margin-top: 60px;
            text-align: right;
        }
        .footer {
            margin-top: 80px;
            text-align: center;
            font-size: 10pt;
            border-top: 1px solid #000;
            padding-top: 15px;
        }
        .placeholder {
            border: 1px dashed #999;
            background-color: #f8f8f8;
            text-align: center;
            font-style: italic;
            color: #666;
            padding: 20px;
            margin: 20px 0;
        }
    </style>
</head>
<body>
    <div class="title">[Title: Company Invoice or Document]</div>

    <div class="header">
        <div class="left">
            [Company Logo]<br>
            Company Name<br>
            Address Line 1<br>
            City, State ZIP
        </div>
        <div class="right">
            Invoice No: [Invoice Number]<br>
            Date: [Date]
        </div>
    </div>

    <div class="address">
        <strong>Bill To:</strong><br>
        [Recipient Name]<br>
        [Recipient Address Line 1]<br>
        [City, State ZIP]
    </div>

    <div class="content">
        <p>Dear [Recipient Name],</p>
        <p>This is to inform you about the [Service/Product] details as per our agreement.</p>
        <p class="centered"><strong>[Any subheading or key sentence]</strong></p>
        <p>The total amount due is $[Amount].</p>
        <p>Please process the payment at your earliest convenience.</p>
    </div>

    <div class="signature">
        Best regards,<br>
        [Signer Name]<br>
        [Title]
    </div>

    <div class="placeholder" style="margin-top: 40px;">
        [Placeholder: Signature or Document Seal]
    </div>

    <div class="footer">
        [Document Footer Text or Page Number]
    </div>
</body>
</html>
